import React,{useEffect,useMemo,useState} from 'react';
import {BrowserRouter,Link,NavLink,Navigate,Outlet,Route,Routes,useLocation,useNavigate,useOutletContext} from 'react-router-dom';
import {Activity,Award,Bell,CalendarDays,Check,ChevronRight,Clipboard,GitCompareArrows,GraduationCap,Heart,LogOut,Mail,MapPin,Menu,MessageCircle,Plus,Radar as RadarIcon,Save,Send,Settings as SettingsIcon,Sparkles,Target,Trash2,Users,X} from 'lucide-react';
import {PolarAngleAxis,PolarGrid,PolarRadiusAxis,Radar,RadarChart,ResponsiveContainer,Tooltip} from 'recharts';
import {AuthProvider,useAuth} from './context/AuthContext';
import ProtectedRoute from './components/ProtectedRoute';
import {supabase} from './lib/supabase';
import {friendlyAuthError,friendlyError} from './lib/errors';
import {buildUniversityRoadmap,calculateRoadmapProgress,formatAdmissionType,formatEventSource,formatEventType,formatRequirementValue,getRoadmapStatus,majorContextText,roadmapStatusLabel,shiftDate,toIsoDate} from './lib/roadmap';

const tiers={1:'Международный / национальный уровень',2:'Региональный лидер или заметный результат',3:'Стабильная роль в школе / городе',4:'Разовая или начальная школьная активность'};
const countries=['USA','UK','Netherlands','Hong Kong','Kazakhstan','Switzerland'];
const draftKey='northstar-profile-draft-v2';
const emptyProfile={full_name:'',school:'',city:'',country:'Kazakhstan',grade:11,target_major:'Computer Science',gpa_unweighted:3.7,gpa_weighted:null,gpa_scale:4,english_exam_type:'IELTS',english_score:6.5,sat:null,act:null,ent_unt:null,nuet:null,interview_ready:false,annual_budget:20000,currency:'USD',needs_full_aid:false,portfolio_public:false,target_countries:['USA','UK'],narrative_about_me:''};

function Landing(){return <div className="min-h-screen bg-[#f8f6f1]"><header className="max-w-6xl mx-auto px-5 py-5 flex justify-between items-center"><Link to="/" className="flex items-center gap-2 font-extrabold"><span className="logo-mark">✦</span>northstar</Link><Link className="btn-ghost" to="/login">Войти</Link></header><main className="max-w-6xl mx-auto px-5 py-10"><section className="grid md:grid-cols-[1.1fr_.9fr] gap-10 items-center min-h-[72vh]"><div><div className="eyebrow"><span className="dot"/>профиль · оценка · маршрут</div><h1 className="display text-6xl md:text-8xl leading-[.92] mt-6">Твой следующий шаг уже <em>виден.</em></h1><p className="text-lg muted max-w-xl mt-7 leading-relaxed">Northstar собирает академический профиль, оценивает связность Major / Spike и превращает поступление в календарь конкретных действий.</p><Link className="btn-primary mt-8" to="/login">Собрать мой маршрут <ChevronRight size={18}/></Link></div><div className="hero-card"><div className="compass">✦</div><div className="mt-8 text-white"><div className="text-xs uppercase tracking-[.2em] text-[#c7d8c3]">в одном кабинете</div><h2 className="display text-4xl mt-2">Портфолио.<br/>Шансы. Дедлайны.</h2><p className="text-[#c7d8c3] mt-3">С данными в Postgres и персональной AI-оценкой.</p></div></div></section></main></div>}

function Login(){const {user,configured,signIn,signInWithGoogle,signUp,resetPassword}=useAuth();const navigate=useNavigate();const location=useLocation();const [mode,setMode]=useState('login');const [form,setForm]=useState({name:'',email:'',password:''});const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);if(user)return <Navigate to={location.state?.from||'/portfolio'} replace/>;async function submit(e){e.preventDefault();setBusy(true);setMessage('');let result;if(mode==='forgot')result=await resetPassword(form.email);else if(mode==='login')result=await signIn(form.email,form.password);else result=await signUp(form.email,form.password,form.name);setBusy(false);if(result.error)setMessage(friendlyAuthError(result.error));else if(mode==='login')navigate(location.state?.from||'/portfolio');else if(mode==='forgot')setMessage('Проверь почту — мы отправили ссылку для нового пароля.');else setMessage('Проверь почту и подтверди регистрацию.')}async function google(){setBusy(true);setMessage('');const {error}=await signInWithGoogle();if(error){setMessage(friendlyAuthError(error));setBusy(false)}}const title=mode==='login'?'С возвращением.':mode==='signup'?'Создай свой маршрут.':'Восстановить доступ.';return <div className="min-h-screen bg-[#17352e] grid place-items-center p-5"><form onSubmit={submit} className="panel p-7 w-full max-w-md"><Link to="/" className="flex items-center gap-2 font-extrabold"><span className="logo-mark">✦</span>northstar</Link><h1 className="display text-4xl mt-7">{title}</h1><p className="muted mt-2">{mode==='forgot'?'Укажи email — Supabase пришлёт безопасную ссылку.':'Профиль и прогресс будут храниться в защищённой базе.'}</p>{mode!=='forgot'&&<><button type="button" className="btn-ghost w-full justify-center mt-6" disabled={busy||!configured} onClick={google}><span className="font-extrabold text-lg">G</span>Продолжить с Google</button><div className="flex items-center gap-3 my-4 text-xs muted"><span className="h-px bg-black/10 flex-1"/><span>или по email</span><span className="h-px bg-black/10 flex-1"/></div></>}{mode==='signup'&&<Field label="Имя"><input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field>}<Field label="Email"><input required type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></Field>{mode!=='forgot'&&<Field label="Пароль"><input required minLength="8" type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/></Field>}{!configured&&<p className="error mt-4">Добавь VITE_SUPABASE_URL и VITE_SUPABASE_ANON_KEY.</p>}{message&&<p className={message.startsWith('Проверь')?'notice mt-4':'error mt-4'}>{message}</p>}<button disabled={busy||!configured} className="btn-primary w-full justify-center mt-6">{busy?'Подключаем…':mode==='login'?'Войти':mode==='signup'?'Зарегистрироваться':'Отправить ссылку'}</button>{mode==='login'&&<button type="button" className="btn-ghost w-full justify-center mt-3" onClick={()=>{setMode('forgot');setMessage('')}}>Забыли пароль?</button>}<button type="button" className="btn-ghost w-full justify-center mt-3" onClick={()=>{setMode(mode==='login'?'signup':'login');setMessage('')}}>{mode==='login'?'Нет аккаунта? Создать':'Вернуться ко входу'}</button></form></div>}

function ResetPassword(){const {updatePassword}=useAuth();const navigate=useNavigate();const [password,setPassword]=useState('');const [confirm,setConfirm]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);async function submit(e){e.preventDefault();if(password.length<8){setError('Пароль должен содержать минимум 8 символов.');return}if(password!==confirm){setError('Пароли не совпадают.');return}setBusy(true);setError('');const {error:updateError}=await updatePassword(password);setBusy(false);if(updateError)setError(friendlyAuthError(updateError));else navigate('/portfolio',{replace:true})}return <div className="min-h-screen bg-[#17352e] grid place-items-center p-5"><form onSubmit={submit} className="panel p-7 w-full max-w-md"><Link to="/" className="flex items-center gap-2 font-extrabold"><span className="logo-mark">✦</span>northstar</Link><h1 className="display text-4xl mt-7">Новый пароль.</h1><p className="muted mt-2">Ссылка из письма создаёт временную защищённую сессию.</p><Field label="Новый пароль"><input required minLength="8" type="password" value={password} onChange={e=>setPassword(e.target.value)}/></Field><Field label="Повтори пароль"><input required minLength="8" type="password" value={confirm} onChange={e=>setConfirm(e.target.value)}/></Field>{error&&<p className="error mt-4">{error}</p>}<button disabled={busy} className="btn-primary w-full justify-center mt-6">{busy?'Сохраняем…':'Сохранить пароль'}</button></form></div>}

function Shell(){const location=useLocation();const [navOpen,setNavOpen]=useState(false);const {user,signOut}=useAuth();const [profile,setProfile]=useState(null);const [universities,setUniversities]=useState([]);const [loading,setLoading]=useState(true);const [loadError,setLoadError]=useState('');useEffect(()=>{(async()=>{const [profileResult,universityResult]=await Promise.all([supabase.from('profiles').select('*').eq('user_id',user.id).maybeSingle(),supabase.from('universities').select('*').order('qs_rank')]);if(profileResult.error||!profileResult.data){setLoadError('Профиль не найден. Примени миграции Supabase и обнови страницу.');setLoading(false);return}setProfile(profileResult.data);setUniversities(universityResult.data||[]);setLoading(false)})()},[user.id]);useEffect(()=>setNavOpen(false),[location.pathname]);if(loading)return <div className="app-loader"><Sparkles className="twinkle"/><p>Загружаем профиль…</p></div>;if(loadError)return <div className="app-loader"><div className="panel p-7 max-w-md text-center"><h1 className="display text-3xl">Нужно подключить профиль.</h1><p className="error mt-3">{loadError}</p><button className="btn-primary mt-5" onClick={()=>window.location.reload()}>Обновить</button><button className="btn-ghost mt-3" onClick={signOut}>Выйти</button></div></div>;return <div className="min-h-screen bg-[#f8f6f1] aurora-page"><header className="app-header"><Link to="/" className="flex items-center gap-2 font-extrabold"><span className="logo-mark">✦</span>northstar</Link><button className="icon-button nav-toggle" aria-label="Открыть меню" aria-expanded={navOpen} aria-controls="primary-navigation" onClick={()=>setNavOpen(value=>!value)}>{navOpen?<X size={18}/>:<Menu size={18}/>}</button><nav id="primary-navigation" className={'app-nav '+(navOpen?'open':'')}><NavLink to="/portfolio">Портфолио</NavLink><NavLink to="/evaluator">AI-оценка</NavLink><NavLink to="/assistant">AI-ассистент</NavLink><NavLink to="/universities">Вузы</NavLink><NavLink to="/compare">Сравнение</NavLink><NavLink to="/roadmap">Roadmap</NavLink><NavLink to="/networking">Письма</NavLink><NavLink to="/settings">Настройки</NavLink></nav><button className="icon-button" aria-label="Выйти" onClick={signOut}><LogOut size={18}/></button></header><DeadlineNotifications user={user} profile={profile}/><main className="max-w-6xl mx-auto px-5 py-8"><Outlet context={{profile,setProfile,universities}}/></main></div>}
const useWorkspace=()=>useOutletContext();

function DeadlineNotifications({user,profile}){const [items,setItems]=useState([]);useEffect(()=>{if(!profile?.id)return;(async()=>{const today=new Date();today.setHours(0,0,0,0);const end=new Date(today);end.setDate(end.getDate()+7);const {data:events}=await supabase.from('calendar_events').select('id,title,date').eq('profile_id',profile.id).eq('completed',false).gte('date',today.toISOString().slice(0,10)).lte('date',end.toISOString().slice(0,10));const rows=(events||[]).map(event=>{const eventDate=new Date(`${event.date}T00:00:00`);const days=Math.max(0,Math.round((eventDate-today)/86400000));const reminder_days=days<=1?1:days<=3?3:7;return {user_id:user.id,profile_id:profile.id,event_id:event.id,reminder_days,channel:'in_app'}});if(rows.length)await supabase.from('deadline_notifications').upsert(rows,{onConflict:'event_id,reminder_days,channel',ignoreDuplicates:true});const {data}=await supabase.from('deadline_notifications').select('id,reminder_days,calendar_events(title,date)').eq('profile_id',profile.id).is('shown_at',null).order('created_at').limit(3);setItems(data||[])})()},[profile?.id,user.id]);async function dismiss(id){setItems(current=>current.filter(item=>item.id!==id));await supabase.from('deadline_notifications').update({shown_at:new Date().toISOString()}).eq('id',id)}if(!items.length)return null;return <div className="max-w-6xl mx-auto px-5 pt-4 space-y-2">{items.map(item=><div className="notice flex items-center gap-3" key={item.id}><Bell size={18}/><div className="flex-1"><b>Этап через {item.reminder_days===1?'1 день':`${item.reminder_days} дня`}:</b> {item.calendar_events?.title}<small className="demo">{item.calendar_events?.date}</small></div><button className="icon-button" aria-label="Скрыть уведомление" onClick={()=>dismiss(item.id)}><X size={16}/></button></div>)}</div>}

function Portfolio(){const {profile,setProfile}=useWorkspace();const [draft,setDraft]=useState(()=>{try{return {...emptyProfile,...profile,...JSON.parse(localStorage.getItem(draftKey)||'{}')}}catch{return {...emptyProfile,...profile}}});const [step,setStep]=useState(0);const [activities,setActivities]=useState([]);const [apExams,setApExams]=useState([]);const [olympiads,setOlympiads]=useState([]);const [message,setMessage]=useState('');const [saving,setSaving]=useState(false);useEffect(()=>localStorage.setItem(draftKey,JSON.stringify(draft)),[draft]);useEffect(()=>{Promise.all([supabase.from('activities').select('*').eq('profile_id',profile.id),supabase.from('ap_exams').select('*').eq('profile_id',profile.id),supabase.from('olympiads').select('*').eq('profile_id',profile.id)]).then(([a,ap,o])=>{setActivities(a.data||[]);setApExams(ap.data||[]);setOlympiads(o.data||[])})},[profile.id]);const set=(key,value)=>setDraft(x=>({...x,[key]:value}));const toggleCountry=c=>set('target_countries',draft.target_countries.includes(c)?draft.target_countries.filter(x=>x!==c):[...draft.target_countries,c]);async function save(){setSaving(true);const payload={...draft,id:profile.id,user_id:profile.user_id};['created_at','updated_at','is_demo','leaderboard_score'].forEach(key=>delete payload[key]);const {data,error}=await supabase.from('profiles').upsert(payload).select().single();if(error)setMessage(friendlyError(error));else{setProfile(data);localStorage.removeItem(draftKey);setMessage('Профиль сохранён в Postgres.')}setSaving(false)}async function addActivity(){const {data,error}=await supabase.from('activities').insert({profile_id:profile.id,name:'Новая активность',tier:'4',hours_per_week:2,description:''}).select().single();if(error)setMessage(friendlyError(error));else if(data)setActivities(x=>[...x,data])}async function updateActivity(id,patch){setActivities(x=>x.map(item=>item.id===id?{...item,...patch}:item));const {error}=await supabase.from('activities').update(patch).eq('id',id);if(error)setMessage(friendlyError(error))}async function removeActivity(id){setActivities(x=>x.filter(item=>item.id!==id));await supabase.from('activities').delete().eq('id',id)}async function addAp(){const {data,error}=await supabase.from('ap_exams').insert({profile_id:profile.id,subject:'AP Computer Science',score:1}).select().single();if(error)setMessage(friendlyError(error));else if(data)setApExams(x=>[...x,data])}async function updateAp(id,patch){setApExams(x=>x.map(item=>item.id===id?{...item,...patch}:item));const {error}=await supabase.from('ap_exams').update(patch).eq('id',id);if(error)setMessage(friendlyError(error))}async function removeAp(id){setApExams(x=>x.filter(item=>item.id!==id));await supabase.from('ap_exams').delete().eq('id',id)}async function addOlympiad(){const {data,error}=await supabase.from('olympiads').insert({profile_id:profile.id,name:'Новая награда',level:'school',result:'participant'}).select().single();if(error)setMessage(friendlyError(error));else if(data)setOlympiads(x=>[...x,data])}async function updateOlympiad(id,patch){setOlympiads(x=>x.map(item=>item.id===id?{...item,...patch}:item));const {error}=await supabase.from('olympiads').update(patch).eq('id',id);if(error)setMessage(friendlyError(error))}const kz=draft.target_countries.includes('Kazakhstan');const hk=draft.target_countries.includes('Hong Kong');const labels=['Контекст','Major / Spike','Тесты','Активности','AP курсы','История'];return <section><PageTitle icon={<GraduationCap/>} eyebrow="защищённый профиль" title="Портфолио, которое складывается в историю." sub="Основной путь — последовательно, но вкладки сверху остаются кликабельными. Черновик сохраняется между шагами."/><div className="flex gap-2 mt-7 overflow-x-auto pb-2">{labels.map((label,index)=><button type="button" className={'step-pill '+(step===index?'active':'')} onClick={()=>setStep(index)} key={label}>{index+1}. {label}</button>)}</div><div className="panel p-6 md:p-8 mt-3">{step===0&&<div className="grid md:grid-cols-2 gap-5"><label className="label">Имя<input value={draft.full_name||''} onChange={e=>set('full_name',e.target.value)}/></label><label className="label">Школа<input value={draft.school||''} onChange={e=>set('school',e.target.value)}/></label><label className="label">Город<input value={draft.city||''} onChange={e=>set('city',e.target.value)}/></label><label className="label">Класс<select value={draft.grade||11} onChange={e=>set('grade',Number(e.target.value))}><option value="9">9</option><option value="10">10</option><option value="11">11</option><option value="12">12</option></select></label></div>}{step===1&&<div className="space-y-5"><label className="label">Major / Spike<input value={draft.target_major||''} onChange={e=>set('target_major',e.target.value)} placeholder="Computer Science / AI / Economics"/></label><label className="label">О себе<textarea rows="5" value={draft.narrative_about_me||''} onChange={e=>set('narrative_about_me',e.target.value)}/></label><div><div className="label mb-2">Целевые страны</div><div className="flex flex-wrap gap-2">{countries.map(country=><button type="button" key={country} className={'choice '+(draft.target_countries.includes(country)?'chosen':'')} onClick={()=>toggleCountry(country)}>{draft.target_countries.includes(country)&&<Check size={15}/>} {country}</button>)}</div></div></div>}{step===2&&<div className="grid md:grid-cols-2 gap-5"><label className="label">GPA<input type="number" min="0" max={draft.gpa_scale||4} step=".01" value={draft.gpa_unweighted??''} onChange={e=>set('gpa_unweighted',e.target.value===''?null:Number(e.target.value))}/><small className="hint">Шкала: от 0 до {draft.gpa_scale||4}.</small></label><label className="label">Шкала GPA<input type="number" min="1" max="100" value={draft.gpa_scale||4} onChange={e=>set('gpa_scale',Number(e.target.value))}/></label><label className="label">IELTS / TOEFL<input type="number" step=".5" value={draft.english_score??''} onChange={e=>set('english_score',e.target.value===''?null:Number(e.target.value))}/></label>{!kz&&<label className="label">SAT<input type="number" min="400" max="1600" value={draft.sat??''} onChange={e=>set('sat',e.target.value===''?null:Number(e.target.value))}/></label>}{kz&&<label className="label">NUET<input type="number" min="0" max="240" value={draft.nuet??''} onChange={e=>set('nuet',e.target.value===''?null:Number(e.target.value))}/></label>}{hk&&<label className="check-row"><input type="checkbox" checked={Boolean(draft.interview_ready)} onChange={e=>set('interview_ready',e.target.checked)}/><span><b>Готовность к интервью</b><small className="demo">Для Гонконга это влияет на оценку.</small></span></label>}</div>}{step===3&&<><div className="flex justify-between items-center"><div><h3 className="font-extrabold text-xl">Активности</h3><p className="muted text-sm">Уровень Tier и часы в неделю учитываются AI-оценкой.</p></div><button type="button" className="btn-ghost" onClick={addActivity}><Plus size={16}/>Добавить</button></div><div className="space-y-4 mt-5">{activities.map(activity=><div className="activity-editor" key={activity.id}><input value={activity.name} onChange={e=>updateActivity(activity.id,{name:e.target.value})}/><select value={activity.tier} onChange={e=>updateActivity(activity.id,{tier:e.target.value})}>{Object.entries(tiers).map(([key,value])=><option key={key} value={key}>Tier {key} — {value}</option>)}</select><input type="number" min="0" max="168" value={activity.hours_per_week} onChange={e=>updateActivity(activity.id,{hours_per_week:Number(e.target.value)})} aria-label="Часов в неделю"/><textarea rows="2" value={activity.description||''} onChange={e=>updateActivity(activity.id,{description:e.target.value})}/><button type="button" className="icon-button" aria-label="Удалить активность" onClick={()=>removeActivity(activity.id)}><Trash2 size={16}/></button></div>)}</div></>}{step===4&&<><div className="flex justify-between items-center"><div><h3 className="font-extrabold text-xl">AP курсы</h3><p className="muted text-sm">Предметы и баллы от 1 до 5 попадут в контекст ассистента и roadmap.</p></div><button type="button" className="btn-ghost" onClick={addAp}><Plus size={16}/>Добавить</button></div><div className="space-y-3 mt-5">{apExams.map(ap=><div className="compact-row" key={ap.id}><Activity size={17}/><input value={ap.subject} onChange={e=>updateAp(ap.id,{subject:e.target.value})}/><input type="number" min="1" max="5" value={ap.score} onChange={e=>updateAp(ap.id,{score:Number(e.target.value)})} aria-label="Оценка AP"/><button type="button" className="icon-button" aria-label="Удалить AP курс" onClick={()=>removeAp(ap.id)}><Trash2 size={16}/></button></div>)}</div></>}{step===5&&<div className="space-y-7"><div className="grid md:grid-cols-2 gap-5"><div><h3 className="font-extrabold text-xl">IB, языки и рекомендации</h3><label className="label mt-5">IB total score<input type="number" min="0" max="45" value={draft.ib_score??''} onChange={e=>set('ib_score',e.target.value===''?null:Number(e.target.value))}/></label><label className="label mt-5">Языки и уровни<textarea rows="3" value={(Array.isArray(draft.languages)?draft.languages:[]).join(', ')} onChange={e=>set('languages',e.target.value.split(',').map(x=>x.trim()).filter(Boolean))} placeholder="English — B2, Kazakh — C1"/></label><label className="label mt-5">Рекомендательные письма<textarea rows="3" value={(Array.isArray(draft.recommendation_letters)?draft.recommendation_letters:[]).join(', ')} onChange={e=>set('recommendation_letters',e.target.value.split(',').map(x=>x.trim()).filter(Boolean))} placeholder="Math teacher — requested, CS mentor — draft"/></label></div><div><h3 className="font-extrabold text-xl">Финансовая информация</h3><label className="label mt-5">Годовой бюджет<input type="number" value={draft.annual_budget??''} onChange={e=>set('annual_budget',e.target.value===''?null:Number(e.target.value))}/></label><label className="check-row mt-4"><input type="checkbox" checked={Boolean(draft.needs_full_aid)} onChange={e=>set('needs_full_aid',e.target.checked)}/><span><b>Нужна полная финансовая помощь</b><small className="demo">Добавит финансовые дедлайны в roadmap.</small></span></label><label className="label mt-5">Финансовый контекст<textarea rows="3" value={draft.financial_notes||''} onChange={e=>set('financial_notes',e.target.value)} placeholder="Важные обстоятельства для aid-стратегии"/></label></div></div><div><div className="flex justify-between items-center"><h3 className="font-extrabold text-xl">Awards / олимпиады</h3><button type="button" className="btn-ghost" onClick={addOlympiad}><Plus size={16}/>Добавить</button></div>{olympiads.map(item=><div className="compact-row" key={item.id}><Award size={17}/><input value={item.name} onChange={e=>updateOlympiad(item.id,{name:e.target.value})}/><select value={item.level} onChange={e=>updateOlympiad(item.id,{level:e.target.value})}><option value="school">Школьный</option><option value="regional">Региональный</option><option value="national">Национальный</option><option value="international">Международный</option></select><input value={item.result} onChange={e=>updateOlympiad(item.id,{result:e.target.value})} aria-label="Результат"/></div>)}</div><div className="notice"><b>Summary:</b>&nbsp;{activities.length} активностей · {apExams.length} AP · {olympiads.length} наград · {(draft.target_countries||[]).join(', ')||'страны не выбраны'}</div></div>}</div><div className="flex flex-wrap justify-between items-center gap-3 mt-6"><button type="button" className="btn-ghost" disabled={step===0} onClick={()=>setStep(value=>Math.max(0,value-1))}>← Назад</button><span className="source">Шаг {step+1} из {labels.length} · {message}</span><div className="flex gap-2"><button type="button" className="btn-ghost" disabled={step===labels.length-1} onClick={()=>setStep(value=>Math.min(labels.length-1,value+1))}>Продолжить →</button><button type="button" onClick={save} disabled={saving} className="btn-primary"><Save size={16}/>{saving?'Сохраняем…':'Сохранить'}</button></div></div></section>}

function Universities(){const {profile,universities}=useWorkspace();const [leaders,setLeaders]=useState([]);const [leaderCount,setLeaderCount]=useState(0);const [shortlist,setShortlist]=useState(new Set());const [shortlistError,setShortlistError]=useState('');useEffect(()=>{Promise.all([supabase.rpc('get_public_leaderboard',{result_limit:10}),supabase.from('shortlist').select('university_id').eq('profile_id',profile.id)]).then(([leaderResult,shortlistResult])=>{setLeaders(leaderResult.data||[]);setLeaderCount(Number(leaderResult.data?.[0]?.total_count||0));setShortlist(new Set((shortlistResult.data||[]).map(x=>x.university_id)));if(shortlistResult.error)setShortlistError('Не удалось загрузить шортлист.')})},[profile.id]);async function toggleShortlist(universityId){setShortlistError('');if(shortlist.has(universityId)){const {error}=await supabase.from('shortlist').delete().eq('profile_id',profile.id).eq('university_id',universityId);if(error){setShortlistError(friendlyError(error,'Не удалось изменить шортлист.'));return}setShortlist(current=>{const next=new Set(current);next.delete(universityId);return next})}else{const {error}=await supabase.from('shortlist').insert({profile_id:profile.id,university_id:universityId});if(error){setShortlistError(friendlyError(error,'Не удалось изменить шортлист.'));return}setShortlist(current=>new Set([...current,universityId]))}}return <section><PageTitle icon={<MapPin/>} eyebrow="университеты и benchmark" title="Рейтинг — контекст, не решение." sub="QS указан для быстрой навигации; требования и acceptance rate зависят от программы и года."/><div className="flex flex-wrap items-center justify-between gap-3 mt-7"><span className="source">В шортлисте: {shortlist.size}</span><Link className="btn-ghost" to="/compare"><GitCompareArrows size={16}/>Сравнить выбранные</Link></div>{shortlistError&&<p className="error mt-3">{shortlistError}</p>}<div className="grid md:grid-cols-3 gap-4 mt-4">{universities.map(u=>{const selected=shortlist.has(u.id);return <article className="program-card" key={u.id}><div className="flex justify-between items-start gap-3"><UniversityLogo university={u}/><div className="flex flex-col items-end gap-2"><span className="badge bg-[#f2e6df]">QS #{u.qs_rank}</span><span className="source">{formatAdmissionType(u.admission_type)}</span></div></div><h3 className="font-extrabold text-lg mt-4">{u.name}</h3><p className="muted text-sm mt-1">{u.city}, {u.country}</p><div className="mt-4 text-sm">Acceptance: <b>{u.acceptance_rate}%</b> · GPA: <b>{u.gpa_requirement}</b></div><small className="demo">QS 2026; остальные показатели ориентировочные</small><button className={selected?'btn-primary w-full justify-center mt-4':'btn-ghost w-full justify-center mt-4'} onClick={()=>toggleShortlist(u.id)}><Heart size={16} fill={selected?'currentColor':'none'}/>{selected?'В шортлисте ✓':'В шортлист'}</button></article>})}</div><div className="panel p-6 mt-8"><div className="flex items-center gap-2"><Users size={18}/><h3 className="font-extrabold">Лидерборд · {leaderCount} открытых профилей</h3></div><div className="overflow-x-auto mt-4"><table className="w-full min-w-[620px]"><thead><tr><th>#</th><th>Профиль</th><th>Школа</th><th>Major / Spike</th><th>Score</th></tr></thead><tbody>{leaders.map((x,i)=><tr key={`${x.full_name}-${x.school}-${i}`}><td>{i+1}</td><td>{x.full_name}<small className="demo">{x.country}</small></td><td>{x.school}</td><td>{x.target_major}</td><td><b>{x.leaderboard_score}</b></td></tr>)}</tbody></table></div></div></section>}

function UniversityLogo({university}){return <div className="relative w-14 h-14 shrink-0 rounded-2xl bg-[#f2e6df] grid place-items-center overflow-hidden" aria-label={`Логотип ${university.name}`}><span className="display text-2xl text-[#17352e]" aria-hidden="true">{university.name?.[0]||'✦'}</span>{university.logo_url&&<img className="absolute inset-0 w-full h-full object-contain bg-white p-1" src={university.logo_url} alt={`Логотип ${university.name}`} loading="lazy" onError={e=>e.currentTarget.remove()}/>}</div>}

function Compare(){const {profile}=useWorkspace();const [items,setItems]=useState([]);const [total,setTotal]=useState(0);const [loading,setLoading]=useState(true);const [error,setError]=useState('');useEffect(()=>{(async()=>{const {data:rows,count,error:loadError}=await supabase.from('shortlist').select('university_id,created_at,universities(*)',{count:'exact'}).eq('profile_id',profile.id).order('created_at').limit(4);if(loadError){setError(friendlyError(loadError,'Не удалось загрузить сравнение.'));setLoading(false);return}const ids=(rows||[]).map(row=>row.university_id);const {data:evaluations}=ids.length?await supabase.from('ai_evaluations').select('university_id,holistic_score,created_at').eq('profile_id',profile.id).in('university_id',ids).order('created_at',{ascending:false}):{data:[]};const latest={};(evaluations||[]).forEach(item=>{if(!latest[item.university_id])latest[item.university_id]=item});setItems((rows||[]).map(row=>({...row.universities,holistic_score:latest[row.university_id]?.holistic_score})));setTotal(count||0);setLoading(false)})()},[profile.id]);const requirement=(u,key)=>formatRequirementValue(u.other_requirements?.[key]);if(loading)return <div className="app-loader"><Sparkles className="twinkle"/><p>Собираем сравнение…</p></div>;return <section><PageTitle icon={<GitCompareArrows/>} eyebrow="сравнение шортлиста" title="Смотри на различия, а не только на названия." sub="Пороговые баллы и дедлайны берутся из таблицы universities."/>{total>4&&<div className="notice mt-5">Показаны первые 4 вуза из {total}. Убери лишние в шортлисте, чтобы изменить набор.</div>}{!items.length?<div className="empty-state panel mt-8"><Heart size={38}/><h3 className="font-extrabold mt-3">Шортлист пока пуст</h3><Link className="btn-primary mt-5" to="/universities">Выбрать вузы</Link></div>:<div className="overflow-x-auto panel mt-8 max-w-full"><table className="w-full min-w-[900px]"><thead><tr><th>Параметр</th>{items.map(u=><th key={u.id}><div className="flex items-center gap-3"><UniversityLogo university={u}/><span>{u.name}</span></div></th>)}</tr></thead><tbody>{[['QS rank',u=>u.qs_rank?`#${u.qs_rank}`:'—'],['Тип поступления',u=>formatAdmissionType(u.admission_type)],['Acceptance rate',u=>u.acceptance_rate!=null?`${u.acceptance_rate}%`:'—'],['GPA requirement',u=>u.gpa_requirement??'—'],['SAT threshold',u=>u.sat_requirement??requirement(u,'sat')],['SAT average',u=>u.sat_average??'—'],['ACT threshold',u=>u.act_requirement??requirement(u,'act')],['ACT average',u=>u.act_average??'—'],['NUET threshold',u=>u.nuet_requirement??requirement(u,'nuet')],['NUET average',u=>u.nuet_average??'—'],['Tests',u=>requirement(u,'tests')],['Financial aid',u=>requirement(u,'aid')],['Deadline',u=>u.application_deadline||requirement(u,'deadline')],['AI holistic score',u=>u.holistic_score!=null?`${u.holistic_score}/100`:'Запусти AI-оценку на /evaluator']].map(([label,get])=><tr key={label}><td>{label}</td>{items.map(u=><td key={u.id}>{get(u)}{['QS rank','Acceptance rate','GPA requirement','SAT threshold','SAT average','ACT threshold','ACT average','NUET threshold','NUET average','Deadline'].includes(label)&&<small className="demo">demo / проверь у вуза</small>}</td>)}</tr>)}</tbody></table></div>}{error&&<p className="error mt-4">{error}</p>}</section>}

function Evaluator(){const {profile,universities}=useWorkspace();const [universityId,setUniversityId]=useState('');const [evaluation,setEvaluation]=useState(null);const [loading,setLoading]=useState(false);const [phase,setPhase]=useState(0);const phases=['Анализируем профиль…','Проверяем Major / Spike…','Сравниваем с базой поступивших…','Считаем ориентировочные шансы…'];async function evaluate(){if(!universityId)return;setLoading(true);setEvaluation(null);setPhase(0);const timer=setInterval(()=>setPhase(x=>Math.min(x+1,phases.length-1)),900);const {data,error}=await supabase.functions.invoke('evaluate-profile',{body:{universityId}});clearInterval(timer);setLoading(false);if(error){let message=friendlyError(error,'Не удалось запустить AI-оценку.');const status=error.context?.status;if(status===429){message='Дневной лимит ИИ-оценок исчерпан, попробуйте завтра.';try{const payload=await error.context.json();message=payload.error||message}catch{/* keep clear fallback */}}setEvaluation({error:message,rateLimited:status===429})}else setEvaluation(data)}const chart=useMemo(()=>{if(!evaluation||evaluation.error)return[];const avg=evaluation.university.average_admitted_profile||{};return [{axis:'Academics',student:evaluation.academics_score,admitted:avg.Academics||85},{axis:'Extracurriculars',student:evaluation.extracurriculars_score,admitted:avg.Extracurriculars||85},{axis:'Awards',student:evaluation.awards_score,admitted:avg.Awards||85},{axis:'Test Scores',student:evaluation.test_scores_score,admitted:avg['Test Scores']||85}]},[evaluation]);return <section><PageTitle icon={<RadarIcon/>} eyebrow="AI evaluator" title="Цифры плюс связность профиля." sub={`Оценка учитывает Major / Spike «${profile.target_major||'не задан'}», региональные требования и не является гарантией поступления.`}/><div className="panel p-6 mt-8 flex flex-col md:flex-row gap-4"><select value={universityId} onChange={e=>setUniversityId(e.target.value)}><option value="">Выбери университет</option>{universities.map(u=><option key={u.id} value={u.id}>QS #{u.qs_rank} · {u.name}</option>)}</select><button className="btn-primary whitespace-nowrap" disabled={!universityId||loading} onClick={evaluate}><Sparkles size={16}/>Запустить анализ</button></div>{loading&&<div className="panel p-7 mt-5"><div className="ai-skeleton"><Sparkles className="twinkle"/><div><b>{phases[phase]}</b><div className="skeleton-line mt-3"/><div className="skeleton-line short mt-2"/></div></div><div className="analysis-steps mt-6">{phases.map((x,i)=><span className={i<=phase?'done':''} key={x}>{i<phase?'✓':i+1} {x}</span>)}</div></div>}{evaluation?.error&&<div className="notice mt-5">{evaluation.error}{!evaluation.rateLimited&&' Проверь Edge Function и переменные окружения.'}</div>}{evaluation&&!evaluation.error&&<div className="grid lg:grid-cols-2 gap-5 mt-5"><div className="panel p-6"><div className="flex justify-between items-start"><div><div className="eyebrow">ориентировочная оценка</div><h3 className="display text-4xl mt-2">{evaluation.holistic_score}/100</h3></div><span className="badge bg-[#fff0d6]">не гарантия</span></div><div className="h-[330px] mt-4"><ResponsiveContainer><RadarChart data={chart}><PolarGrid/><PolarAngleAxis dataKey="axis" tick={{fontSize:11}}/><PolarRadiusAxis domain={[0,100]} tick={false}/><Radar name="Твой профиль" dataKey="student" stroke="#e76443" fill="#e76443" fillOpacity={.3}/><Radar name="Средний поступивший" dataKey="admitted" stroke="#17352e" fill="#17352e" fillOpacity={.12}/><Tooltip/></RadarChart></ResponsiveContainer></div></div><div className="panel p-6"><h3 className="font-extrabold text-xl">Coherence / Spike</h3><p className="mt-4 leading-relaxed">{evaluation.coherence_notes}</p><p className="notice mt-4">{evaluation.spike_alignment_notes}</p><h4 className="font-extrabold mt-6">Следующие усиления</h4><ul className="space-y-3 mt-3">{evaluation.suggestions?.map(x=><li className="reason" key={x}><Check size={16}/>{x}</li>)}</ul></div></div>}</section>}

function Assistant(){const {user}=useAuth();const {profile}=useWorkspace();const [messages,setMessages]=useState([]);const [input,setInput]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [aiMode,setAiMode]=useState('fallback');useEffect(()=>{supabase.from('ai_chat_messages').select('id,role,content,created_at').eq('user_id',user.id).order('created_at').then(({data,error:loadError})=>{if(loadError)setError('Не удалось загрузить историю чата.');else setMessages(data||[])})},[user.id]);async function send(e){e.preventDefault();const message=input.trim();if(!message||busy)return;setInput('');setError('');setBusy(true);const userMessage={id:`local-user-${Date.now()}`,role:'user',content:message};const assistantId=`local-assistant-${Date.now()}`;setMessages(current=>[...current,userMessage,{id:assistantId,role:'assistant',content:''}]);try{const {data:{session}}=await supabase.auth.getSession();const response=await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/assistant-chat`,{method:'POST',headers:{Authorization:`Bearer ${session?.access_token}`,'Content-Type':'application/json',apikey:import.meta.env.VITE_SUPABASE_ANON_KEY},body:JSON.stringify({message})});if(!response.ok){const payload=await response.json().catch(()=>({}));throw new Error(payload.error||'Ассистент временно недоступен.')}setAiMode(response.headers.get('X-Northstar-AI-Mode')||'fallback');if(!response.body)throw new Error('Браузер не поддерживает потоковый ответ.');const reader=response.body.getReader();const decoder=new TextDecoder();while(true){const {done,value}=await reader.read();if(done)break;const chunk=decoder.decode(value,{stream:true});setMessages(current=>current.map(item=>item.id===assistantId?{...item,content:item.content+chunk}:item))}}catch(sendError){setMessages(current=>current.filter(item=>item.id!==assistantId));setError(friendlyError(sendError,'Не удалось получить ответ ассистента.'))}finally{setBusy(false)}}return <section><PageTitle icon={<MessageCircle/>} eyebrow="AI-ассистент" title="Эссе и стратегия — с контекстом твоего профиля." sub={`Ассистент видит сохранённый профиль, шортлист и roadmap под ${profile.target_major||'твоё направление'}, но не гарантирует поступление и не выдумывает достижения.`}/><div className={aiMode==='gemini'?'notice mt-6':'panel p-4 mt-6 flex items-start gap-3'}><Sparkles size={18}/><div><b>{aiMode==='gemini'?'Персональный AI-анализ Gemini':'Режим базовых рекомендаций'}</b><p className="muted text-sm mt-1">{aiMode==='gemini'?'Ответ строится внешней моделью с минимизированным контекстом.':'Работает без внешнего ключа: сравнивает твои данные с требованиями и использует библиотеку essay-чеклистов. Для свободного AI-анализа нужен GEMINI_API_KEY.'}</p></div></div><div className="panel mt-4 overflow-hidden"><div className="h-[55vh] min-h-[360px] overflow-y-auto p-5 md:p-7 space-y-4" aria-live="polite">{!messages.length&&!busy&&<div className="empty-state"><Sparkles size={34}/><h3 className="font-extrabold mt-3">С чего начнём?</h3><p className="muted max-w-lg">Пришли черновик эссе для разбора или спроси, как усилить стратегию под выбранные вузы.</p></div>}{messages.map(item=><div key={item.id} className={item.role==='user'?'ml-auto max-w-[85%] rounded-2xl bg-[#17352e] text-white p-4':'mr-auto max-w-[90%] rounded-2xl bg-[#f2e6df] p-4'}><div className="text-xs font-bold uppercase tracking-wider opacity-60 mb-1">{item.role==='user'?'Ты':'Northstar AI'}</div><p className="whitespace-pre-wrap leading-relaxed">{item.content||<span className="inline-flex gap-1"><span className="animate-pulse">●</span><span className="animate-pulse">●</span><span className="animate-pulse">●</span></span>}</p></div>)}</div><form onSubmit={send} className="border-t border-black/10 p-4 flex gap-3"><textarea rows="2" maxLength="12000" value={input} onChange={e=>setInput(e.target.value)} placeholder="Вставь абзац эссе или задай вопрос о стратегии…" aria-label="Сообщение AI-ассистенту"/><button className="btn-primary self-end" disabled={busy||!input.trim()}><Send size={16}/><span className="hidden sm:inline">Отправить</span></button></form></div>{error&&<p className="error mt-4">{error}</p>}<p className="source mt-3">История хранится в защищённой базе и удаляется вместе с аккаунтом.</p></section>}

function Roadmap(){
  const {profile}=useWorkspace();
  const [events,setEvents]=useState([]);
  const [subtasks,setSubtasks]=useState([]);
  const [history,setHistory]=useState([]);
  const [activities,setActivities]=useState([]);
  const [apExams,setApExams]=useState([]);
  const [olympiads,setOlympiads]=useState([]);
  const [draggedId,setDraggedId]=useState(null);
  const [sourceFilter,setSourceFilter]=useState('all');
  const [viewMode,setViewMode]=useState('timeline');
  const [expanded,setExpanded]=useState({});
  const [busy,setBusy]=useState(false);
  const [message,setMessage]=useState('');

  const load=async()=>{
    const [{data:eventsData},{data:activityData},{data:apData},{data:awardData}]=await Promise.all([
      supabase.from('calendar_events').select('*').eq('profile_id',profile.id).order('date'),
      supabase.from('activities').select('name,tier,hours_per_week').eq('profile_id',profile.id),
      supabase.from('ap_exams').select('subject,score').eq('profile_id',profile.id),
      supabase.from('olympiads').select('name,level,result').eq('profile_id',profile.id),
    ]);
    const loadedEvents=eventsData||[];
    const ids=loadedEvents.map(event=>event.id);
    let loadedSubtasks=[];
    let loadedHistory=[];
    if(ids.length){
      const [subtaskResult,historyResult]=await Promise.all([
        supabase.from('roadmap_subtasks').select('*').in('calendar_event_id',ids).order('due_date').order('sort_order'),
        supabase.from('roadmap_event_history').select('*').in('calendar_event_id',ids).order('created_at',{ascending:false}),
      ]);
      loadedSubtasks=subtaskResult.data||[];
      loadedHistory=historyResult.data||[];
    }
    setEvents(loadedEvents);
    setSubtasks(loadedSubtasks);
    setHistory(loadedHistory);
    setActivities(activityData||[]);
    setApExams(apData||[]);
    setOlympiads(awardData||[]);
  };
  useEffect(()=>{load()},[profile.id]);

  const makeProfilePlan=(key,title,date,type,description,appPath,estimatedMinutes,items)=>({
    key:`profile:${key}`,
    event:{
      title,
      date:toIsoDate(date),
      type,
      description,
      roadmap_key:`profile:${key}`,
      metadata:{stage:key,why:description,app_path:appPath,estimated_minutes:estimatedMinutes,change_reason:'Этап пересчитан после обновления портфолио'},
    },
    subtasks:items.map((item,index)=>({title:item,due_date:toIsoDate(shiftDate(date,(index-items.length+1)*3)),estimated_minutes:Math.max(20,Math.round(estimatedMinutes/items.length)),sort_order:index})),
  });

  async function generate(){
    setBusy(true);
    setMessage('');
    if(profile.needs_full_aid)await supabase.rpc('add_financial_aid_deadlines',{target_profile_id:profile.id});
    const [{data:shortlist,error},{data:previousAuto}]=await Promise.all([
      supabase.from('shortlist').select('universities(*)').eq('profile_id',profile.id).order('created_at'),
      supabase.from('calendar_events').select('id,roadmap_key').eq('profile_id',profile.id).eq('source','auto_ai_roadmap'),
    ]);
    if(error){setMessage(friendlyError(error,'Не удалось загрузить шортлист.'));setBusy(false);return}

    const today=new Date();
    today.setHours(12,0,0,0);
    const portfolioSummary=`${activities.length} активностей, ${apExams.length} AP-курсов, ${olympiads.length} наград`;
    const plans=(shortlist||[]).flatMap((row,index)=>{
      if(!row.universities)return[];
      return buildUniversityRoadmap(row.universities,profile,{today,fallbackDays:180+index*21,portfolioSummary}).plans;
    });
    const countries=(profile.target_countries||[]).map(value=>value.toLowerCase());
    const majorIntro=majorContextText(profile.target_major);

    if(countries.some(value=>value.includes('kazakhstan'))&&!profile.nuet)plans.push(makeProfilePlan('nuet','Сдать/пересдать NUET',shiftDate(today,28),'exam',`${majorIntro}NUET нужен для оценки готовности к поступлению в Казахстане.`,'/portfolio',180,['Пройти диагностический вариант','Разобрать слабые темы','Забронировать дату экзамена']));
    if(countries.some(value=>value.includes('usa')||value.includes('hong kong'))&&!profile.sat)plans.push(makeProfilePlan('sat','Пробный SAT и план подготовки',shiftDate(today,21),'exam',`${majorIntro}Диагностика SAT покажет разрыв до требований вузов шортлиста.`,'/portfolio',210,['Пройти полный пробный тест','Составить список слабых тем','Выбрать дату следующей попытки']));
    if(!profile.english_score)plans.push(makeProfilePlan('english','Запланировать IELTS / TOEFL',shiftDate(today,14),'exam',`${majorIntro}Языковой результат нужен для проверки минимальных требований программ.`,'/portfolio',150,['Выбрать IELTS или TOEFL','Пройти диагностический тест','Забронировать дату экзамена']));
    if(!activities.length)plans.push(makeProfilePlan('activity',profile.target_major?`Проект под ${profile.target_major}`:'Профильный проект',shiftDate(today,14),'task','Проект с измеримым результатом усилит связность Major / Spike.','/portfolio',240,['Сформулировать проблему и результат','Собрать минимальную версию проекта','Добавить результат в портфолио']));
    if(!apExams.length&&!profile.ib_score)plans.push(makeProfilePlan('advanced-courses','План AP / IB',shiftDate(today,30),'task','Продвинутые предметы подтверждают академическую готовность к выбранному Major / Spike.','/portfolio',120,['Выбрать релевантные предметы','Проверить доступные даты и форматы','Добавить предметы в портфолио']));

    if(!plans.length){
      setMessage('Добавь вуз в шортлист или заполни портфолио — тогда появятся персональные этапы.');
      setBusy(false);
      return;
    }

    const eventRows=plans.map(plan=>({...plan.event,profile_id:profile.id,source:'auto_ai_roadmap'}));
    const {data:saved,error:saveError}=await supabase.from('calendar_events').upsert(eventRows,{onConflict:'profile_id,roadmap_key'}).select('id,roadmap_key');
    if(saveError){
      setMessage(friendlyError(saveError));
      setBusy(false);
      return;
    }

    const eventByKey=new Map((saved||[]).map(event=>[event.roadmap_key,event.id]));
    const subtaskRows=plans.flatMap(plan=>(plan.subtasks||[]).map(task=>({...task,calendar_event_id:eventByKey.get(plan.key)}))).filter(task=>task.calendar_event_id);
    const {error:subtaskError}=subtaskRows.length?await supabase.from('roadmap_subtasks').upsert(subtaskRows,{onConflict:'calendar_event_id,title'}):{error:null};
    if(subtaskError){
      setMessage(friendlyError(subtaskError,'Этапы сохранены, но чеклисты не обновились.'));
      await load();
      setBusy(false);
      return;
    }

    const keepIds=new Set((saved||[]).map(event=>event.id));
    const staleIds=(previousAuto||[]).map(event=>event.id).filter(id=>!keepIds.has(id));
    if(staleIds.length)await supabase.from('calendar_events').delete().in('id',staleIds);
    setMessage(`Roadmap обновлён: ${plans.length} этапов и ${subtaskRows.length} конкретных подзадач.`);
    await load();
    setBusy(false);
  }

  async function updateEvent(id,patch,reason='Этап изменён пользователем'){
    const current=events.find(event=>event.id===id);
    const payload={...patch,metadata:{...(current?.metadata||{}),change_reason:reason}};
    setEvents(items=>items.map(item=>item.id===id?{...item,...payload}:item));
    const {error}=await supabase.from('calendar_events').update(payload).eq('id',id);
    if(error)setMessage(friendlyError(error));else await load();
  }

  async function updateSubtask(id,patch){
    setSubtasks(items=>items.map(item=>item.id===id?{...item,...patch}:item));
    const {error}=await supabase.from('roadmap_subtasks').update(patch).eq('id',id);
    if(error)setMessage(friendlyError(error));
  }

  async function addSubtask(event){
    const {data,error}=await supabase.from('roadmap_subtasks').insert({calendar_event_id:event.id,title:'Новая подзадача',due_date:event.date,estimated_minutes:30,sort_order:subtasks.filter(task=>task.calendar_event_id===event.id).length}).select().single();
    if(error)setMessage(friendlyError(error));else if(data)setSubtasks(items=>[...items,data]);
  }

  async function addManual(){
    const {data,error}=await supabase.from('calendar_events').insert({profile_id:profile.id,title:'Новая задача',date:new Date().toISOString().slice(0,10),type:'task',description:'Добавлено вручную',source:'manual',metadata:{stage:'manual',why:'Пользовательский этап',app_path:'/roadmap',estimated_minutes:30}}).select().single();
    if(error)setMessage(friendlyError(error));else if(data)setEvents(items=>[...items,data].sort((a,b)=>a.date.localeCompare(b.date)));
  }

  async function dropOnEvent(target){
    const dragged=events.find(event=>event.id===draggedId);
    if(!dragged||dragged.id===target.id)return;
    setDraggedId(null);
    await updateEvent(dragged.id,{date:target.date},`Этап перенесён вручную на дату «${target.title}»`);
  }

  const overallProgress=calculateRoadmapProgress(events,subtasks);
  const universities=[...new Set(events.map(event=>event.metadata?.university).filter(Boolean))];
  const filteredEvents=events.filter(event=>sourceFilter==='all'||event.source===sourceFilter);
  const byUniversity=filteredEvents.reduce((groups,event)=>{
    const name=event.metadata?.university||'Общий план';
    groups[name]=[...(groups[name]||[]),event];
    return groups;
  },{});
  const monthLabel=date=>new Date(`${date}T00:00:00`).toLocaleDateString('ru-RU',{month:'long',year:'numeric'});
  const toggleExpanded=id=>setExpanded(current=>({...current,[id]:!(current[id]??true)}));

  const renderCard=(event,index)=>{
    const eventSubtasks=subtasks.filter(task=>task.calendar_event_id===event.id);
    const eventHistory=history.filter(item=>item.calendar_event_id===event.id);
    const status=getRoadmapStatus(event);
    const isOpen=expanded[event.id]??true;
    return <article className={`roadmap-card source-${event.source} status-${status} ${draggedId===event.id?'is-dragging':''}`} key={event.id} draggable onDragStart={()=>setDraggedId(event.id)} onDragEnd={()=>setDraggedId(null)} onDragOver={e=>e.preventDefault()} onDrop={()=>dropOnEvent(event)}><div className="roadmap-card-head"><label className="roadmap-complete"><input type="checkbox" checked={Boolean(event.completed)} onChange={e=>updateEvent(event.id,{completed:e.target.checked},e.target.checked?'Этап отмечен выполненным':'Этап возвращён в работу')} aria-label={`Выполнить этап: ${event.title}`}/></label><div className="flex-1 min-w-0"><div className="flex flex-wrap items-center gap-2"><span className={`roadmap-status-dot ${status}`} aria-hidden="true"/><span className="source">{roadmapStatusLabel(status)}</span><span className="source">· {new Date(`${event.date}T00:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</span><span className="source">· {formatEventType(event.type)}</span></div><h3 className={`font-extrabold text-lg mt-1 ${event.completed?'line-through':''}`}>{event.title}</h3></div><span className={`source-chip source-${event.source}`}>{formatEventSource(event.source)}</span><button className={`icon-button roadmap-expand ${isOpen?'open':''}`} onClick={()=>toggleExpanded(event.id)} aria-label={isOpen?'Свернуть этап':'Развернуть этап'} aria-expanded={isOpen}><ChevronRight size={18}/></button></div>{isOpen&&<div className="roadmap-card-body"><label className="label">Название этапа<input value={event.title} onChange={e=>setEvents(items=>items.map(item=>item.id===event.id?{...item,title:e.target.value}:item))} onBlur={e=>updateEvent(event.id,{title:e.target.value},'Название этапа изменено вручную')}/></label><label className="label mt-3">Дата<input type="date" value={event.date} onChange={e=>updateEvent(event.id,{date:e.target.value},'Дата этапа перенесена вручную')} aria-label="Дата этапа"/></label><p className="mt-4 leading-relaxed">{event.description}</p><div className="flex flex-wrap gap-3 mt-3"><span className="badge bg-[#fff0d6]">≈ {event.metadata?.estimated_minutes||30} мин</span>{event.metadata?.app_path&&<Link className="btn-ghost" to={event.metadata.app_path}>Открыть связанный раздел <ChevronRight size={15}/></Link>}</div><div className="mt-5 border-t border-black/10 pt-4"><div className="flex justify-between items-center gap-3"><b>Чеклист</b><button className="btn-ghost" onClick={()=>addSubtask(event)}><Plus size={14}/>Подзадача</button></div><div className="space-y-3 mt-3">{eventSubtasks.map(task=><div className="roadmap-subtask" key={task.id}><input type="checkbox" checked={task.completed} onChange={e=>updateSubtask(task.id,{completed:e.target.checked})} aria-label={`Выполнить: ${task.title}`}/><input value={task.title} onChange={e=>setSubtasks(items=>items.map(item=>item.id===task.id?{...item,title:e.target.value}:item))} onBlur={e=>updateSubtask(task.id,{title:e.target.value})}/><input type="date" value={task.due_date} onChange={e=>updateSubtask(task.id,{due_date:e.target.value})} aria-label="Срок подзадачи"/><small className="source">{task.estimated_minutes} мин</small></div>)}</div></div>{eventHistory.length>0&&<details className="mt-4"><summary className="cursor-pointer font-bold text-sm">История изменений ({eventHistory.length})</summary><div className="space-y-2 mt-3">{eventHistory.slice(0,6).map(item=><div className="source" key={item.id}>{new Date(item.created_at).toLocaleString('ru-RU')}: {item.reason}{item.field_name==='date'&&<> · {item.old_value} → {item.new_value}</>}</div>)}</div></details>}<button className="btn-ghost mt-4" onClick={()=>downloadIcs(event)}><CalendarDays size={15}/>Синхронизировать этап</button></div>}</article>;
  };

  return <section><PageTitle icon={<CalendarDays/>} eyebrow="roadmap + calendar" title="План действий, а не список дат." sub="Переключай временную шкалу и группировку по вузам. Цвет показывает источник и состояние, а карточки можно свернуть."/><div className="roadmap-toolbar mt-7"><div className="flex flex-wrap gap-2"><button className="btn-primary" disabled={busy} onClick={generate}><Sparkles size={16}/>{busy?'Пересчитываем…':'Пересчитать roadmap'}</button><button className="btn-ghost" onClick={addManual}><Plus size={16}/>Добавить свой этап</button><button className="btn-ghost" disabled={!events.length} onClick={()=>downloadRoadmapIcs(events,subtasks)}><CalendarDays size={16}/>Синхронизировать с телефоном</button></div><div className="roadmap-segmented" aria-label="Вид roadmap"><button className={viewMode==='timeline'?'active':''} onClick={()=>setViewMode('timeline')}>По времени</button><button className={viewMode==='university'?'active':''} onClick={()=>setViewMode('university')}>По вузам</button></div></div>{message&&<p className="notice mt-4">{message}</p>}<div className="roadmap-progress panel p-5 mt-6"><div className="flex justify-between gap-3"><b>Общий прогресс</b><span>{overallProgress}%</span></div><div className="h-2 rounded-full bg-black/10 mt-2 overflow-hidden"><div className="h-full bg-[#e76443] rounded-full transition-all" style={{width:`${overallProgress}%`}}/></div>{universities.map(university=>{const progress=calculateRoadmapProgress(events,subtasks,university);return <div className="mt-4" key={university}><div className="flex justify-between text-sm"><span>{university}</span><b>{progress}%</b></div><div className="h-1.5 rounded-full bg-black/10 mt-1 overflow-hidden"><div className="h-full bg-[#17352e] rounded-full" style={{width:`${progress}%`}}/></div></div>})}</div><div className="roadmap-filters mt-5"><span className="source">Показывать:</span>{[{value:'all',label:'Все'},{value:'manual',label:'Вручную'},{value:'auto_ai_roadmap',label:'Персональный план'},{value:'auto_financial_aid',label:'Финансовая помощь'}].map(option=><button key={option.value} className={sourceFilter===option.value?'active':''} onClick={()=>setSourceFilter(option.value)}>{option.label}</button>)}</div><div className="roadmap-legend mt-3"><span><i className="roadmap-status-dot overdue"/>Просрочено</span><span><i className="roadmap-status-dot soon"/>Скоро</span><span><i className="roadmap-status-dot ontrack"/>В графике</span><span><i className="roadmap-status-dot completed"/>Выполнено</span></div><p className="source mt-4">Перетащи карточку на другой этап, чтобы назначить ей ту же дату. На телефоне используй поле даты.</p>{viewMode==='timeline'?<div className="roadmap-timeline mt-5">{filteredEvents.map((event,index)=>{const showMonth=index===0||monthLabel(event.date)!==monthLabel(filteredEvents[index-1].date);return <React.Fragment key={event.id}>{showMonth&&<h2 className="roadmap-month">{monthLabel(event.date)}</h2>}<div className="roadmap-timeline-row"><div className={`roadmap-timeline-point ${getRoadmapStatus(event)}`} aria-hidden="true"/>{renderCard(event,index)}</div></React.Fragment>})}</div>:<div className="space-y-4 mt-5">{Object.entries(byUniversity).map(([university,items])=><details className="roadmap-university-group" key={university} open><summary><span>{university}</span><span className="source">{items.length} этапов · {calculateRoadmapProgress(items,subtasks)}%</span></summary><div className="space-y-4 mt-4">{items.map(renderCard)}</div></details>)}</div>}{!filteredEvents.length&&<div className="empty-state panel mt-8"><CalendarDays size={38}/><h3 className="font-extrabold mt-3">Нет этапов для этого фильтра</h3><p className="muted">Выбери другой источник или пересчитай roadmap.</p></div>}</section>;
}

function Networking(){const {profile,universities}=useWorkspace();const [kind,setKind]=useState('research');const [university,setUniversity]=useState(universities[0]?.name||'университета');const generated=useMemo(()=>kind==='research'?`Subject: Prospective student interested in ${profile.target_major}\n\nDear Professor,\n\nMy name is ${profile.full_name||'[Name]'}, and I am a student at ${profile.school||'[School]'} exploring ${profile.target_major}. I am particularly interested in your work at ${university}. My current portfolio focuses on ${profile.narrative_about_me||'[briefly describe your strongest project]'} and I would be grateful to learn whether there may be a small, well-scoped way to contribute to your research.\n\nI can share a concise portfolio and am happy to complete a trial task.\n\nBest regards,\n${profile.full_name||'[Name]'}`:`Subject: Financial aid reconsideration request\n\nDear Financial Aid Office,\n\nThank you for reviewing my application to ${university}. I am writing to respectfully ask whether my financial aid package can be reconsidered. My family’s realistic annual contribution is ${profile.currency} ${Number(profile.annual_budget||0).toLocaleString()}, and I require substantial support to enroll.\n\nI can provide updated financial documents and context upon request. ${profile.narrative_about_me||''}\n\nSincerely,\n${profile.full_name||'[Name]'}`,[kind,university,profile]);const [draft,setDraft]=useState(generated);useEffect(()=>setDraft(generated),[generated]);return <section><PageTitle icon={<Mail/>} eyebrow="networking utility" title="Черновик, который звучит как ты." sub="Northstar использует профиль для первого варианта. Перед отправкой обязательно проверь факты и адресата."/><div className="grid md:grid-cols-[.7fr_1.3fr] gap-5 mt-8"><div className="panel p-6"><Field label="Тип письма"><select value={kind} onChange={e=>setKind(e.target.value)}><option value="research">Research inquiry</option><option value="aid">Financial aid appeal</option></select></Field><Field label="Университет"><select value={university} onChange={e=>setUniversity(e.target.value)}>{universities.map(u=><option key={u.id}>{u.name}</option>)}</select></Field><div className="notice mt-5">Не отправляй массово. Добавь конкретную работу профессора или детали aid package.</div></div><div className="panel p-6"><textarea className="email-editor" value={draft} onChange={e=>setDraft(e.target.value)}/><button className="btn-primary mt-4" onClick={()=>navigator.clipboard.writeText(draft)}><Clipboard size={16}/>Скопировать черновик</button></div></div></section>}

function Settings(){const {signOut}=useAuth();const navigate=useNavigate();const [confirmOpen,setConfirmOpen]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState('');async function deleteAccount(){setBusy(true);setError('');const {error:invokeError}=await supabase.functions.invoke('delete-account');if(invokeError){let message=friendlyError(invokeError,'Не удалось удалить аккаунт.');try{const payload=await invokeError.context?.json();message=payload?.error||message}catch{/* keep SDK error */}setError(message);setBusy(false);return}await signOut();navigate('/',{replace:true})}return <section><PageTitle icon={<SettingsIcon/>} eyebrow="настройки аккаунта" title="Ты контролируешь свои данные." sub="Удаление аккаунта необратимо: профиль, активности, оценки, roadmap и шортлист удалятся каскадно."/><div className="panel p-6 mt-8 border border-red-200"><h2 className="font-extrabold text-xl">Опасная зона</h2><p className="muted mt-2">Это действие удалит запись Supabase Auth и все связанные данные.</p><button className="btn-ghost mt-5 text-red-700" onClick={()=>setConfirmOpen(true)}><Trash2 size={16}/>Удалить аккаунт</button>{error&&<p className="error mt-4">{error}</p>}</div>{confirmOpen&&<div className="fixed inset-0 z-50 bg-black/60 grid place-items-center p-5" role="dialog" aria-modal="true" aria-labelledby="delete-account-title"><div className="panel p-7 w-full max-w-md"><div className="flex justify-between gap-4"><h2 id="delete-account-title" className="display text-3xl">Точно удалить аккаунт?</h2><button className="icon-button" aria-label="Закрыть подтверждение" disabled={busy} onClick={()=>setConfirmOpen(false)}><X size={18}/></button></div><p className="muted mt-4">Вернуть профиль, AI-оценки, события календаря и шортлист после удаления будет невозможно.</p><div className="flex flex-wrap justify-end gap-3 mt-6"><button className="btn-ghost" disabled={busy} onClick={()=>setConfirmOpen(false)}>Отмена</button><button className="btn-primary bg-red-700" disabled={busy} onClick={deleteAccount}><Trash2 size={16}/>{busy?'Удаляем…':'Да, удалить навсегда'}</button></div></div></div>}</section>}

function PageTitle({icon,eyebrow,title,sub}){return <div><div className="eyebrow">{icon}<span>{eyebrow}</span></div><h1 className="display text-5xl mt-4">{title}</h1><p className="muted mt-3 max-w-3xl">{sub}</p></div>}
function Field({label,children}){return <label className="block mt-5"><span className="label">{label}</span><div className="mt-2">{children}</div></label>}
function escapeIcs(value){return String(value||'').replaceAll('\\\\','\\\\\\\\').replaceAll(';','\\\\;').replaceAll(',','\\\\,').replace(/\\r?\\n/g,'\\\\n')}
function calendarEntry(item){return ['BEGIN:VEVENT',`UID:${escapeIcs(item.id)}@northstar`,`DTSTART;VALUE=DATE:${item.date.replaceAll('-','')}`,`SUMMARY:${escapeIcs(item.title)}`,`DESCRIPTION:${escapeIcs(item.description)}`,item.completed?'STATUS:COMPLETED':'STATUS:CONFIRMED','END:VEVENT'].join('\\r\\n')}
function saveCalendar(entries,filename){const content=['BEGIN:VCALENDAR','VERSION:2.0','CALSCALE:GREGORIAN','PRODID:-//Northstar//Roadmap//RU',...entries.map(calendarEntry),'END:VCALENDAR'].join('\\r\\n');const url=URL.createObjectURL(new Blob([content],{type:'text/calendar;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=filename;document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),0)}
function downloadIcs(event){saveCalendar([event],'northstar-event.ics')}
function downloadRoadmapIcs(events,subtasks){const taskEntries=subtasks.map(task=>({id:task.id,date:task.due_date,title:`Подзадача: ${task.title}`,description:'Часть персонального roadmap Northstar',completed:task.completed}));saveCalendar([...events,...taskEntries],'northstar-roadmap.ics')}

export default function App(){return <AuthProvider><BrowserRouter><Routes><Route path="/" element={<Landing/>}/><Route path="/login" element={<Login/>}/><Route path="/reset-password" element={<ResetPassword/>}/><Route element={<ProtectedRoute><Shell/></ProtectedRoute>}><Route path="/portfolio" element={<Portfolio/>}/><Route path="/evaluator" element={<Evaluator/>}/><Route path="/assistant" element={<Assistant/>}/><Route path="/universities" element={<Universities/>}/><Route path="/compare" element={<Compare/>}/><Route path="/roadmap" element={<Roadmap/>}/><Route path="/networking" element={<Networking/>}/><Route path="/settings" element={<Settings/>}/></Route><Route path="*" element={<Navigate to="/" replace/>}/></Routes></BrowserRouter></AuthProvider>}
